//
// sequence utils, operating on any std::vector<T> whose T supports operator==
//

// number of leading elements shared by a and b
template <typename T>
size_t common_prefix_len(const std::vector<T> & a, const std::vector<T> & b) {
    const size_t max_idx = std::min(a.size(), b.size());

    for (size_t i = 0; i < max_idx; ++i) {
        if (a[i] == b[i]) {
            continue;
        }

        return i;
    }

    return max_idx;
}

// number of trailing elements shared by a and b
template <typename T>
size_t common_suffix_len(const std::vector<T> & a, const std::vector<T> & b) {
    const size_t max_idx = std::min(a.size(), b.size());

    for (size_t i = 0; i < max_idx; ++i) {
        if (a[a.size() - 1 - i] != b[b.size() - 1 - i]) {
            return i;
        }
    }

    return max_idx;
}

// common prefix length of a and b, as a fraction of b's size (0 when b is empty)
template <typename T>
float lcp_similarity(const std::vector<T> & a, const std::vector<T> & b) {
    if (b.empty()) {
        return 0.0f;
    }

    return float(common_prefix_len(a, b)) / b.size();
}
