//! `tokutil` — generic sequence utilities.
//!
//! Helpers for comparing sequences of any `T: PartialEq`, operating on slices.

pub mod prefix;

pub use prefix::{common_prefix_len, common_suffix_len, lcp_similarity};

//! Sequence comparison helpers over slices of any `T: PartialEq`.

/// Number of leading elements shared by `a` and `b`.
pub fn common_prefix_len<T: PartialEq>(a: &[T], b: &[T]) -> usize {
    a.iter().zip(b.iter()).take_while(|(x, y)| x == y).count()
}

/// Number of trailing elements shared by `a` and `b`.
pub fn common_suffix_len<T: PartialEq>(a: &[T], b: &[T]) -> usize {
    a.iter().rev().zip(b.iter().rev()).take_while(|(x, y)| x == y).count()
}

/// Common prefix length of `a` and `b`, as a fraction of `b`'s length (0 when `b` is empty).
pub fn lcp_similarity<T: PartialEq>(a: &[T], b: &[T]) -> f64 {
    if b.is_empty() {
        return 0.0;
    }

    common_prefix_len(a, b) as f64 / b.len() as f64
}

